_install_shim 'readlink' '#!/bin/sh
if command -v readlink >/dev/null 2>&1; then exec readlink "$@"; fi
# Minimal readlink -f implementation
target="$1"
while [ -L "$target" ]; do
    dir=$(dirname "$target")
    target=$(readlink "$target" 2>/dev/null || ls -l "$target" | sed "s/.* -> //")
    case "$target" in
        /*) ;;
        *) target="$dir/$target" ;;
    esac
done
echo "$target"'

