_install_shim 'file' '#!/bin/sh
if command -v file >/dev/null 2>&1; then exec file "$@"; fi
for f in "$@"; do
    if [ -f "$f" ]; then
        # Read first bytes to detect type
        head -c 4 "$f" 2>/dev/null | od -A n -t x1 | head -1 | while read -r hex; do
            case "$hex" in
                "7f 45 4c 46") echo "$f: ELF executable" ;;
                "25 50 44 46") echo "$f: PDF document" ;;
                "50 4b 03 04") echo "$f: Zip archive" ;;
                "1f 8b") echo "$f: gzip compressed data" ;;
                "42 5a 68") echo "$f: bzip2 compressed data" ;;
                "fd 37 7a 58") echo "$f: XZ compressed data" ;;
                "89 50 4e 47") echo "$f: PNG image" ;;
                "ff d8 ff") echo "$f: JPEG image" ;;
                "47 49 46 38") echo "$f: GIF image" ;;
                "52 61 72 21") echo "$f: RAR archive" ;;
                "75 73 74 61") echo "$f: tar archive" ;;
                *) echo "$f: data" ;;
            esac
        done
    elif [ -d "$f" ]; then
        echo "$f: directory"
    else
        echo "$f: cannot open (No such file or directory)" >&2
    fi
done'

