_install_shim 'time' '#!/bin/sh
if command -v time >/dev/null 2>&1 && [ "$(type time 2>&1)" != "time is /usr/bin/time" ]; then
    exec time "$@"
fi
# Minimal time
start=$(date +%s%N 2>/dev/null || date +%s)
"$@"
rc=$?
end=$(date +%s%N 2>/dev/null || date +%s)
elapsed=$(( (end - start) / 1000000 ))
echo "real    0m$((elapsed/1000)).$((elapsed%1000))s"
echo "user    0m0.000s"
echo "sys     0m0.000s"
exit $rc'

