_install_shim 'factor' '#!/bin/sh
if command -v factor >/dev/null 2>&1; then exec factor "$@"; fi
# Minimal factor
n="$1"
if [ -z "$n" ]; then echo "Usage: factor <number>" >&2; exit 1; fi
echo -n "$n: "
i=2
while [ $i -le $n ]; do
    while [ $((n % i)) -eq 0 ]; do
        echo -n "$i "
        n=$((n / i))
    done
    i=$((i + 1))
done
echo'

_install_shim 'seq' '#!/bin/sh
if command -v seq >/dev/null 2>&1; then exec seq "$@"; fi
# Minimal seq
case $# in
    1) i=1; e=$1; s=1 ;;
    2) i=$1; e=$2; s=1 ;;
    3) i=$1; s=$2; e=$3 ;;
    *) echo "Usage: seq [FIRST] [INCREMENT] LAST" >&2; exit 1 ;;
esac
while [ $i -le $e ]; do echo $i; i=$((i + s)); done'

