# Count installed shims
echo "[quro-commands] Installed $(ls -1 "$SHIM_DIR" 2>/dev/null | wc -l) commands in $SHIM_DIR"

# ============================================================
# SHELL COMPATIBILITY LAYER
# ============================================================

# Ensure /bin/sh exists and works
if [ ! -x /bin/sh ] && [ -x /usr/bin/sh ]; then
    ln -sf /usr/bin/sh /bin/sh 2>/dev/null || true
fi

# Ensure common shell config files exist
for f in /etc/profile /etc/bash.bashrc /etc/environment; do
    if [ ! -f "$f" ]; then
        touch "$f" 2>/dev/null || true
    fi
done

# Create /etc/shells if missing (needed for chsh)
if [ ! -f /etc/shells ]; then
    cat > /etc/shells 2>/dev/null << 'SHELLS'
/bin/sh
/bin/bash
/usr/bin/sh
/usr/bin/bash
SHELLS
fi

# Ensure /tmp exists with proper permissions
chmod 1777 /tmp 2>/dev/null || true

echo "[quro-commands] Shell compatibility layer installed"
